function solve(input) {
    const seen = new Set();
    const balances = new Map();

    for (const record of input) {
        if (seen.has(record.eventId)) continue;
        seen.add(record.eventId);

        const account = record.account;
        const delta = record.delta;

        const current = balances.get(account) || 0;
        balances.set(account, current + delta);
    }

    const accounts = Array.from(balances.keys());
    accounts.sort((a, b) => {
        if (a < b) return -1;
        if (a > b) return 1;
        return 0;
    });

    return accounts.map(account => [account, balances.get(account)]);
}
