function solve(input) {
    const { nodes, edges } = input;
    const nodeSet = new Set(nodes);
    const inDegree = new Map();
    const adjacency = new Map();

    for (const node of nodes) {
        inDegree.set(node, 0);
        adjacency.set(node, []);
    }

    const seenEdges = new Set();
    for (const [u, v] of edges) {
        if (u === v) {
            return null;
        }
        const key = u + '\0' + v;
        if (seenEdges.has(key)) continue;
        seenEdges.add(key);
        inDegree.set(v, inDegree.get(v) + 1);
        adjacency.get(u).push(v);
    }

    // Use a sorted structure to always pick lexicographically smallest
    // We'll maintain a sorted array of available nodes
    const available = [];
    for (const [node, deg] of inDegree) {
        if (deg === 0) {
            available.push(node);
        }
    }
    available.sort();

    const result = [];
    while (available.length > 0) {
        // Pick the lexicographically smallest
        const node = available.shift();
        result.push(node);

        const neighbors = adjacency.get(node);
        for (const neighbor of neighbors) {
            const newDeg = inDegree.get(neighbor) - 1;
            inDegree.set(neighbor, newDeg);
            if (newDeg === 0) {
                // Insert into available keeping it sorted
                // Binary search for insertion point
                let lo = 0, hi = available.length;
                while (lo < hi) {
                    const mid = (lo + hi) >> 1;
                    if (available[mid] < neighbor) {
                        lo = mid + 1;
                    } else {
                        hi = mid;
                    }
                }
                available.splice(lo, 0, neighbor);
            }
        }
    }

    if (result.length !== nodes.length) {
        return null;
    }

    return result;
}
