function solve(input) {
    const cache = new Map();
    const results = [];

    for (const op of input) {
        if (op.op === "put") {
            const { t, key, value, ttl } = op;
            if (ttl === 0) {
                cache.delete(key);
            } else {
                cache.set(key, { value, expiresAt: t + ttl });
            }
        } else if (op.op === "get") {
            const { t, key } = op;
            const entry = cache.get(key);
            if (entry === undefined) {
                results.push(null);
            } else if (t >= entry.expiresAt) {
                cache.delete(key);
                results.push(null);
            } else {
                results.push(entry.value);
            }
        } else if (op.op === "delete") {
            const { key } = op;
            cache.delete(key);
        }
    }

    return results;
}
