function solve(input) {
  const { document, pointer } = input;

  if (pointer === '') {
    return { found: true, value: document };
  }

  if (typeof pointer !== 'string' || pointer[0] !== '/') {
    return { found: false };
  }

  const parts = pointer.slice(1).split('/');

  let current = document;

  for (let i = 0; i < parts.length; i++) {
    let token = parts[i];

    // Decode ~1 to / first, then ~0 to ~
    token = token.replace(/~1/g, '/').replace(/~0/g, '~');

    if (current === null || current === undefined) {
      return { found: false };
    }

    if (Array.isArray(current)) {
      // Array index must be canonical nonnegative decimal integer
      if (token === '') {
        return { found: false };
      }
      // Check canonical: no leading zeros (except "0" itself), no negative, digits only
      if (!/^(0|[1-9]\d*)$/.test(token)) {
        return { found: false };
      }
      const idx = parseInt(token, 10);
      if (idx >= current.length) {
        return { found: false };
      }
      current = current[idx];
    } else if (typeof current === 'object') {
      // Use only own object properties
      if (!Object.prototype.hasOwnProperty.call(current, token)) {
        return { found: false };
      }
      current = current[token];
    } else {
      // current is a primitive (string, number, boolean) - cannot traverse further
      return { found: false };
    }
  }

  return { found: true, value: current };
}
