        // Actually, we process row by row.

        const row = [];
        let field = '';
        let inQuotes = false;
        let fieldStarted = false;

        while (i < len) {
            const ch = input[i];

            if (inQuotes) {
                if (ch === '"') {
                    if (i + 1 < len && input[i + 1] === '"') {
                        // Doubled quote
                        field += '"';
                        i += 2;
                    } else {
                        // End of quoted field
                        inQuotes = false;
                        i++;
                    }
                } else {
                    field += ch;
                    i++;
                }
            } else {
                if (ch === '"' && !fieldStarted) {
                    // Start of quoted field
                    inQuotes = true;
                    fieldStarted = true;
                    i++;
                } else if (ch === ',') {
                    // End of field
                    row.push(field);
                    field = '';
                    fieldStarted = false;
